 public function enqueue_gutenberg_assets(){
  if(!current_user_can('use_nirmaan_builder')||!current_user_can('use_nirmaan_modules')||!current_user_can('edit_nirmaan_content'))return;
  $screen=get_current_screen();if(!$screen||empty($screen->post_type)||!in_array($screen->post_type,get_post_types(array('public'=>true),'names'),true))return;
  wp_enqueue_script('nirmaan-builder-gutenberg',NIRMAAN_BUILDER_URL.'assets/js/gutenberg.js',array('wp-plugins','wp-edit-post','wp-element','wp-components','wp-data','wp-i18n'),NIRMAAN_BUILDER_VERSION,true);
  wp_set_script_translations('nirmaan-builder-gutenberg','nirmaan-builder',NIRMAAN_BUILDER_PATH.'languages');
  wp_localize_script('nirmaan-builder-gutenberg','NirmaanBuilderGutenbergConfig',array('builderUrl'=>admin_url('admin.php?page=nirmaan-editor'),'label'=>__('Nirmaan Builder','nirmaan-builder')));
 }
 public function save_builder_mode($post_id,$post){
  if(!$post||'auto-draft'===$post->post_status||wp_is_post_autosave($post_id)||wp_is_post_revision($post_id))return;
  if(!isset($_POST['nirmaan_builder_mode_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['nirmaan_builder_mode_nonce'])),'nirmaan_builder_save_mode'))return;
  if(!current_user_can('use_nirmaan_builder')||!current_user_can('edit_nirmaan_content')||!current_user_can('edit_post',$post_id))return;
  update_post_meta($post_id,'_nirmaan_builder_enabled',isset($_POST['nirmaan_builder_enabled'])?1:0);
 }
 public function add_builder_metabox(){foreach(get_post_types(array('public'=>true,'show_ui'=>true),'names') as $type)add_meta_box('nirmaan-builder','Nirmaan Builder',array($this,'render_builder_metabox'),$type,'side','high');}
