 public function row_builder_link($actions,$post){if(!is_object($post)||!current_user_can('use_nirmaan_builder')||!current_user_can('edit_nirmaan_content')||!current_user_can('edit_post',$post->ID))return $actions;$url=add_query_arg(array('page'=>'nirmaan-editor','post_id'=>$post->ID),admin_url('admin.php'));$actions['nirmaan_builder']='<a href="'.esc_url($url).'">'.esc_html__('Edit with Nirmaan Builder','nirmaan-builder').'</a>';return $actions;}
