lude" multiple size="3" aria-label="Include conditions"><?php $this->condition_options($inc,true);?></select></td><td><select name="exclude" multiple size="3" aria-label="Exclude conditions"><?php $this->condition_options($exc,true);?></select></td><td><button class="button nirmaan-save-template-rules" data-id="<?php echo esc_attr($t->ID);?>"><?php esc_html_e('Save Rules','nirmaan-builder'); ?></button></td><?php $part_settings=get_post_meta($t->ID,'_nirmaan_part_settings',true);$part_settings=is_array($part_settings)?$part_settings:array();foreach(array('header','body','footer') as $part):$ps=$part_settings[$part]??array();$active=!isset($ps['active'])||!empty($ps['active']);$part_condition=$ps['condition']??'';?><td><a class="button button-small" href="<?php echo esc_url($base.$part);?>">Edit</a><label class="nb-part-control"><input type="checkbox" name="part_active_<?php echo esc_attr($part);?>" <?php checked($active);?>> Active</label><select name="part_condition_<?php echo esc_attr($part);?>" aria-label="<?php echo esc_attr(ucfirst($part).' display condition');?>"><option value="">All matching template pages</option><?php foreach(array('front_page'=>'Front Page','all_pages'=>'All Pages','all_posts'=>'All Posts','archive'=>'Archives','search'=>'Search Results','404'=>'404 Page','product'=>'Single Products','product_archive'=>'Product Archives','shop'=>'Shop','cart'=>'Cart','checkout'=>'Checkout') as $value=>$label):?><option value="<?php echo esc_attr($value);?>" <?php selected($part_condition,$value);?>><?php echo esc_html($label);?></option><?php endforeach;?></select></td><?php endforeach;?><td><button class="button button-small nirmaan-save-template-details" data-id="<?php echo esc_attr($t->ID);?>"><?php esc_html_e('Save Details','nirmaan-builder'); ?></button> <button class="button button-small nirmaan-save-part-settings" data-id="<?php echo esc_attr($t->ID);?>"><?php esc_html_e('Save Sections','nirmaan-builder'); ?></button> <button class="button button-small nirmaan-duplicate-template" data-id="<?php echo esc_attr($t->ID);?>"><?php esc_html_e('Duplicate','nirmaan-builder'); ?></button> <button class="button button-small nirmaan-delete-template" data-id="<?php echo esc_attr($t->ID);?>"><?php esc_html_e('Delete','nirmaan-builder'); ?></button></td></tr><?php endforeach;?></tbody></table><p class="nb-template-empty-filter" hidden><?php esc_html_e('No templates match this search.','nirmaan-builder'); ?></p></div><?php }
 private function condition_options($selected,$multiple=false){
  $selected=is_array($selected)?$selected:array($selected);
  $options=array('entire_site'=>'Entire Website','front_page'=>'Front Page','all_pages'=>'All Pages','all_posts'=>'All Posts','product'=>'Single Products','product_archive'=>'Product Archives','shop'=>'Shop','cart'=>'Cart','checkout'=>'Checkout','archive'=>'Archives','search'=>'Search Results','404'=>'404 Page');
  foreach($options as $value=>$label){
   $selected_attr=in_array($value,$selected,true)?' selected="selected"':'';
   echo '<option value="'.esc_attr($value).'"'.$selected_attr.'>'.esc_html($label).'</option>';
  }
 }
 public function render_editor(){$post_id=absint($_GET['post_id']??0);$template_id=absint($_GET['template_id']??0);$library_id=absint($_GET['library_id']??0);if(!current_user_can('use_nirmaan_builder')||!current_user_can('use_nirmaan_modules'))wp_die(esc_html__('You cannot access the visual builder.','nirmaan-builder'));if($post_id&&(!current_user_can('edit_nirmaan_content')||!current_user_can('edit_post',$post_id)))wp_die(esc_html__('You cannot edit this content.','nirmaan-builder'));if($template_id&&!current_user_can('manage_nirmaan_templates'))wp_die(esc_html__('You cannot edit theme templates.','nirmaan-builder'));if($library_id&&!current_user_can('manage_nirmaan_library'))wp_die(esc_html__('You cannot edit Library items.','nirmaan-builder'));if(!$post_id&&!$template_id&&!$library_id)wp_die(esc_html__('Select content or a template to edit.','nirmaan-builder'));$part=sanitize_key($_GET['part']??'body');?>
