lder'); ?></button><button id="nirmaan-revisions" class="button" type="button"><?php esc_html_e('Revisions','nirmaan-builder'); ?></button><button id="nirmaan-save-library" class="button"><?php esc_html_e('Save to Library','nirmaan-builder'); ?></button><button id="nirmaan-save" class="button button-primary"><?php esc_html_e('Save','nirmaan-builder'); ?></button></div>
